using System.Collections.Immutable;

namespace AutoModeCodeGenerator.Internal;

/// <summary>
/// 生成文件头与 Emit 入口。具体语法由 <see cref="CodeGeneration.CodeEmitter"/> 按 ClassStyle 分发。
/// </summary>
public static class SourceGeneratorHelper
{
#pragma warning disable RS1035 // 不要使用禁用于分析器的 API
    public static Version DotNetVersion => Environment.Version;
#pragma warning restore RS1035 // 不要使用禁用于分析器的 API

    public static string AutoGenerated => $$"""
//------------------------------------------------------------------------------
// <auto-generated>
//     此代码由工具 {{typeof(SourceGeneratorHelper).Assembly.GetName()}} 生成。
//     运行时版本:{{DotNetVersion}}
//     https://github.com/mccj/AutoModeCodeGenerator
//
//     对此文件的更改可能会导致不正确的行为，并且如果
//     重新生成代码，这些更改将会丢失。
// </auto-generated>
//------------------------------------------------------------------------------

""";

    public static string GeneratorCode(NullableEnum? nullable, ImmutableArray<SourceGeneratorClassInfo> generatorClassInfos)
        => CodeGeneration.CodeEmitter.Emit(nullable, generatorClassInfos);
}
